CREATE DATABASE IF NOT EXISTS retail_analytics CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE retail_analytics;
CREATE TABLE IF NOT EXISTS categories (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS suppliers (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(140) NOT NULL,phone VARCHAR(30),email VARCHAR(160),address VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,sku VARCHAR(60) NOT NULL UNIQUE,category_id INT NOT NULL,price DECIMAL(12,2) NOT NULL CHECK(price>=0),cost_price DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(cost_price>=0),quantity INT NOT NULL DEFAULT 0 CHECK(quantity>=0),min_stock INT NOT NULL DEFAULT 5 CHECK(min_stock>=0),supplier_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_products_category(category_id),INDEX idx_products_stock(quantity,min_stock),CONSTRAINT fk_products_category FOREIGN KEY(category_id) REFERENCES categories(id),CONSTRAINT fk_products_supplier FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sales (id BIGINT AUTO_INCREMENT PRIMARY KEY,subtotal DECIMAL(12,2) NOT NULL,discount DECIMAL(12,2) NOT NULL DEFAULT 0,total DECIMAL(12,2) NOT NULL,payment_method VARCHAR(30) NOT NULL DEFAULT 'Cash',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_sales_created(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sale_items (id BIGINT AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL CHECK(quantity>0),unit_price DECIMAL(12,2) NOT NULL,line_total DECIMAL(12,2) NOT NULL,INDEX idx_sale_items_product(product_id),CONSTRAINT fk_sale_items_sale FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE CASCADE,CONSTRAINT fk_sale_items_product FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS purchases (id BIGINT AUTO_INCREMENT PRIMARY KEY,supplier_id INT NOT NULL,total DECIMAL(12,2) NOT NULL,status ENUM('received') NOT NULL DEFAULT 'received',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_purchases_created(created_at),CONSTRAINT fk_purchases_supplier FOREIGN KEY(supplier_id) REFERENCES suppliers(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS purchase_items (id BIGINT AUTO_INCREMENT PRIMARY KEY,purchase_id BIGINT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL CHECK(quantity>0),unit_cost DECIMAL(12,2) NOT NULL,line_total DECIMAL(12,2) NOT NULL,INDEX idx_purchase_items_product(product_id),CONSTRAINT fk_purchase_items_purchase FOREIGN KEY(purchase_id) REFERENCES purchases(id) ON DELETE CASCADE,CONSTRAINT fk_purchase_items_product FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_movements (id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,movement_type ENUM('opening','adjustment','sale','purchase') NOT NULL,quantity INT NOT NULL,reason VARCHAR(255) NOT NULL,reference_type VARCHAR(30),reference_id BIGINT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_movements_product_date(product_id,created_at),CONSTRAINT fk_movements_product FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS market_trends (id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,source_name VARCHAR(160) NOT NULL,period_days INT NOT NULL,market_change_percent DECIMAL(8,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_market_trends_product_date(product_id,created_at),CONSTRAINT fk_market_trends_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB;
